"""Append-only event journal store."""

from typing import Dict, List, Optional
from events import DomainEvent
from snapshot import AccountSnapshot


class EventStore:
    def __init__(self):
        self._events: Dict[str, List[DomainEvent]] = {}
        self._snapshots: Dict[str, AccountSnapshot] = {}

    def append_events(self, aggregate_id: str, events: List[DomainEvent]) -> None:
        if aggregate_id not in self._events:
            self._events[aggregate_id] = []
        self._events[aggregate_id].extend(events)

    def get_events_after(self, aggregate_id: str, after_version: int) -> List[DomainEvent]:
        all_ev = self._events.get(aggregate_id, [])
        # BUG: Uses >= instead of > for after_version, re-applying events included in snapshot!
        return [e for e in all_ev if e.version >= after_version]

    def save_snapshot(self, snap: AccountSnapshot) -> None:
        self._snapshots[snap.aggregate_id] = snap

    def get_latest_snapshot(self, aggregate_id: str) -> Optional[AccountSnapshot]:
        return self._snapshots.get(aggregate_id)

repo_files.repository.py:
"""Account aggregate repository managing rehydration from snapshot + journal."""

from typing import Optional
from aggregate import BankAccountAggregate
from event_store import EventStore


class AccountRepository:
    def __init__(self, store: EventStore):
        self.store = store

    def load(self, account_id: str) -> Optional[BankAccountAggregate]:
        snap = self.store.get_latest_snapshot(account_id)
        account = BankAccountAggregate(account_id)
        base_version = 0
        if snap:
            account.restore_from_snapshot(snap)
            base_version = snap.version

        events = self.store.get_events_after(account_id, base_version)
        if not snap and not events:
            return None

        for ev in events:
            account.apply_event(ev)
        return account

